INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Glute_Kickback', 'Glute Kickback', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position. As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 9'),
('Goblet_Squat', 'Goblet Squat', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'beginner', 'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position. Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight. At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.'),
('Good_Morning', 'Good Morning', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack. Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment. Reverse the motion by extending through the hips with your glutes and hamstrings. Contin'),
('Good_Morning_off_Pins', 'Good Morning off Pins', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the motion by extending through the hips with your glut'),
('Gorilla_Chin_Crunch', 'Gorilla Chin/Crunch', 'core', ARRAY['arms','back']::text[], 'bodyweight', 'strength', 'intermediate', 'Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width. Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position. As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this po'),
('Groin_and_Back_Stretch', 'Groin and Back Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Sit on the floor with your knees bent and feet together. Interlock your fingers behind your head. This will be your starting position. Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.'),
('Groiners', 'Groiners', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'intermediate', 'Begin in a pushup position on the floor. This will be your starting position. Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so. Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.'),
('Hack_Squat', 'Hack Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal'),
('Hammer_Curls', 'Hammer Curls', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position. Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze th'),
('Hammer_Grip_Incline_DB_Bench_Press', 'Hammer Grip Incline DB Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creatin'),
('Hamstring-SMR', 'Hamstring-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position. Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching. Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for '),
('Hamstring_Stretch', 'Hamstring Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor. Loop a belt, band, or rope over the ball of your foot. This will be your starting position. Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.'),
('Handstand_Push-Ups', 'Handstand Push-Ups', 'shoulders', ARRAY['arms']::text[], 'bodyweight', 'strength', 'expert', 'With your back to the wall bend at the waist and place both hands on the floor at shoulder width. Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down. Slowly lower yourself to the ground as you inhale until your head almost t'),
('Hang_Clean', 'Hang Clean', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.'),
('Hang_Clean_-_Below_the_Knees', 'Hang Clean - Below the Knees', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward. Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, '),
('Hang_Snatch', 'Hang Snatch', 'legs', ARRAY['core','legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiv'),
('Hang_Snatch_-_Below_Knees', 'Hang Snatch - Below Knees', 'legs', ARRAY['core','legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into t'),
('Hanging_Bar_Good_Morning', 'Hanging Bar Good Morning', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the moti'),
('Hanging_Leg_Raise', 'Hanging Leg Raise', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'expert', 'Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position. Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so. Go back slowly to the starting position as you breathe in. Repeat for the recommended amount of repetitions.'),
('Hanging_Pike', 'Hanging Pike', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'expert', 'Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar. Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position. Pull your legs up as you exhale until you almost touch your shins with '),
('Heaving_Snatch_Balance', 'Heaving Snatch Balance', 'legs', ARRAY['core','arms','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with. Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat. Return to a standing position.'),
('Heavy_Bag_Thrust', 'Heavy Bag Thrust', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position. Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body. Receive the bag as it swings back by reversing these steps.'),
('High_Cable_Curls', 'High Cable Curls', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position. Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps. Slowly brin'),
('Hip_Circles_prone', 'Hip Circles (prone)', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position. Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee. Perform this slowly for a number of repetitions, and repeat on the other side.'),
('Hip_Extension_with_Bands', 'Hip Extension with Bands', 'legs', ARRAY['legs']::text[], 'bands', 'strength', 'beginner', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Facing the attachment point of the band, hold on to the column to stabilize yourself. Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight. Return the leg to the starting position.'),
('Hip_Flexion_with_Band', 'Hip Flexion with Band', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Face away from the attachment point of the band. Keeping your head and your chest up, raise your knee up to 90 degrees and pause. Return the leg to the starting position.'),
('Hip_Lift_with_Band', 'Hip Lift with Band', 'legs', ARRAY['legs','legs']::text[], 'bands', 'powerlifting', 'beginner', 'After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move. Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position. Keeping your shoulders on the ground, drive through your heels to raise'),
('Hug_A_Ball', 'Hug A Ball', 'back', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Seat yourself on the floor. Straddle an exercise ball between both legs and lower your hips down toward the floor. Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks.'),
('Hug_Knees_To_Chest', 'Hug Knees To Chest', 'back', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Lie down on your back and pull both knees up to your chest. Hold your arms under the knees, not over (that would put to much pressure on your knee joints). Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.'),
('Hurdle_Hops', 'Hurdle Hops', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Set up a row of hurdles or other small barriers, placing them a few feet apart. Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first hurdle, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.'),
('Hyperextensions_Back_Extensions', 'Hyperextensions (Back Extensions)', 'back', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Lie face down on a hyperextension bench, tucking your ankles securely under the footpads. Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms. Start bending forward'),
('Hyperextensions_With_No_Hyperextension_Bench', 'Hyperextensions With No Hyperextension Bench', 'back', ARRAY['legs','legs']::text[], 'bodyweight', 'strength', 'intermediate', 'With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be '),
('IT_Band_and_Glute_Stretch', 'IT Band and Glute Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position. Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.'),
('Iliotibial_Tract-SMR', 'Iliotibial Tract-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you. Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching. Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.'),
('Inchworm', 'Inchworm', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position. Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight. Keep going until your body is parallel to the ground in a pushup position. Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a ti'),
('Incline_Barbell_Triceps_Extension', 'Incline Barbell Triceps Extension', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width. Lie back on an incline bench set at any angle between 45-75-degrees. Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position. Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationa'),
('Incline_Bench_Pull', 'Incline Bench Pull', 'back', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees. Let the arms hang to your sides fully extended as they point to the floor. Turn the wrists until your hands have a pronated (palms down) grip. Now flare the elbows out. This will be your starting position. As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up '),
('Incline_Cable_Chest_Press', 'Incline Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to the starting position, keeping tension on the cab'),
('Incline_Cable_Flye', 'Incline Cable Flye', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'intermediate', 'To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso). Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand. With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position. With a slight bend of your elbows (in order to prevent stress at the bi'),
('Incline_Dumbbell_Bench_With_Palms_Facing_In', 'Incline Dumbbell Bench With Palms Facing In', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creatin'),
('Incline_Dumbbell_Curl', 'Incline Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a'),
('Incline_Dumbbell_Flyes', 'Incline Dumbbell Flyes', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing'),
('Incline_Dumbbell_Flyes_-_With_A_Twist', 'Incline Dumbbell Flyes - With A Twist', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing'),
('Incline_Dumbbell_Press', 'Incline Dumbbell Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other. Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width. Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Be sure to keep full control of the dumbbells at all times. Then'),
('Incline_Hammer_Curls', 'Incline Hammer Curls', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position. Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary. Continue to the top of the movement and pause, then slowly return to the start position.'),
('Incline_Inner_Biceps_Curl', 'Incline Inner Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand and lie back on an incline bench. The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position. Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose. After a second contr'),
('Incline_Push-Up', 'Incline Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width. Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms. Push body up until arms are extended. Repeat.'),
('Incline_Push-Up_Close-Grip', 'Incline Push-Up Close-Grip', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands next to one another on the bar. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.'),
('Incline_Push-Up_Depth_Jump', 'Incline Push-Up Depth Jump', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps. Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position. Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb'),
('Incline_Push-Up_Medium', 'Incline Push-Up Medium', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.')
